/** Links versioned natural charters to existing characters, titles, public assets and production. */
public final class NaturalPolityData extends NbtSavedData {
 public static final String NAME="sagadyssey_natural_charters_v1";
 public static final Factory<NaturalPolityData> FACTORY=new Factory<>(NaturalPolityData::new,NaturalPolityData::load);
 private final Map<UUID,CompoundTag> sites=new LinkedHashMap<>();
 private final Map<UUID,CompoundTag> decisions=new LinkedHashMap<>();
 public static NaturalPolityData get(MinecraftServer s){return com.jgeted.sagadyssey.worldsim.PersistentDataAccess.getOrCreate(s,FACTORY,NAME);}
 public static NaturalPolityData existing(MinecraftServer s){return s.overworld().getDataStorage().get(FACTORY.type(NAME));}
 public List<CompoundTag> sites(){return sites.values().stream().map(CompoundTag::copy).toList();}
 public List<CompoundTag> decisions(){return decisions.values().stream().map(CompoundTag::copy).toList();}
 public CompoundTag site(UUID id){var t=sites.get(id);return t==null?null:t.copy();}
 CompoundTag governanceSite(UUID id){return sites.get(id);}
 CompoundTag governanceDecision(UUID id){return decisions.get(id);}
 Collection<CompoundTag> governanceDecisions(){return decisions.values();}
 void governanceRecord(CompoundTag t){if(!decisions.containsKey(t.read("Id", UUIDUtil.CODEC).orElseThrow())&&decisions.size()>=256)throw new IllegalStateException("治理记录已满");decisions.put(t.read("Id", UUIDUtil.CODEC).orElseThrow(),t);setDirty();}
 public static NaturalVillageBuilding building(CompoundTag t){return NaturalVillageLifeData.decode(t.getCompoundOrEmpty("Village"));}
 public static String faction(NaturalVillageBuilding b){return "sagadyssey:community_"+b.settlementId();}
 private static boolean alive(MinecraftServer s,UUID p){var c=p==null?null:CharacterRegistryData.get(s).byId(p);return c!=null&&c.alive();}
 public static List<UUID> population(MinecraftServer s,NaturalVillageBuilding b){return HouseholdData.get(s).households().stream().filter(h->Objects.equals(h.settlementId(),b.settlementId())).flatMap(h->h.members().stream()).map(HouseholdMemberRecord::characterId).filter(p->alive(s,p)&&!NaturalHouseholdMigrationData.moving(s,p)).distinct().toList();}
 public static Container inventory(MinecraftServer s,NaturalVillageBuilding b,int i){var l=SupplyFlowService.level(s,b.dimension());var p=NaturalVillageLayout.at(b,NaturalVillageLayout.stores(b).get(i));if(l==null||l.getChunkSource().getChunkNow(p.getX()>>4,p.getZ()>>4)==null||NaturalVillageEconomyData.protects(s,b.dimension(),p))return null;return l.getBlockEntity(p) instanceof Container c?c:null;}
 private static int count(Container c,String id){return c==null?0:SupplyFlowService.count(c,new ItemFingerprint("minecraft:"+id,0));}
 public static int availableFood(MinecraftServer s,NaturalVillageBuilding b){var principal=SubjectRef.household(NaturalVillageLifeData.home(b));var flows=SupplyFlowData.get(s);int sum=0;for(int i:new int[]{0,1})try{int available=SupplyFlowService.available(s,flows.point(NaturalVillageEconomyData.storeId(b,i)),principal,new ItemFingerprint("minecraft:carrot",0),s.overworld().getGameTime());sum+=Math.max(0,available-(i==0?8:0));}catch(NoSuchElementException ignored){}return sum;}
 private static UUID grant(NaturalVillageBuilding b){return ContainerIds.named("charter-public-office:"+b.settlementId());}
 public void enroll(MinecraftServer s){var life=NaturalVillageLifeData.existing(s);if(life==null)return;var politics=PoliticalStateData.get(s);long now=s.overworld().getGameTime();
  for(var v:life.villages())if(v.getBooleanOr("Ready", false)&&sites.size()<4){var b=NaturalVillageLifeData.decode(v);if(sites.containsKey(b.settlementId()))continue;var region=NaturalVillageEconomyData.existing(s);if(region==null||region.row(b.buildingKey())==null)continue;var t=new CompoundTag();t.put("Village",v.copy());t.putInt("Version",NaturalVillageLayout.chartered(b)?2:1);t.putString("Kind",NaturalVillageLayout.chartered(b)?"VILLAGE":"GROUP");t.putString("Condition","STABLE");t.putString("Reason","按实际住宅、岗位和版本化生成规则建立组织");t.putLong("Declared",now);sites.put(b.settlementId(),t);
   if(NaturalVillageLayout.chartered(b)&&politics.titleHolder(b.settlementId())==null){UUID head=NaturalVillageLifeData.person(b,1);if(alive(s,head)){politics.grantTitle(s,b.settlementId(),"聚落公职",faction(b),head,"原生活户户主",now);politics.designateHeir(s,head,"原生活户户主",NaturalVillageLifeData.person(b,0),"原在籍成员",now);}}
   setDirty();
  }
  // Complementary resources and a bounded, low-relief route distinguish a federation from independent villages.
  var ordered=sites.values().stream().sorted(Comparator.comparing(t->building(t).settlementId().toString())).toList();
  for(var farm:ordered){var a=building(farm);if(!NaturalVillageLayout.chartered(a)||NaturalVillageLayout.woodcamp(a)||farm.contains("Realm"))continue;
   for(var wood:ordered){var b=building(wood);if(!NaturalVillageLayout.woodcamp(b)||wood.contains("Realm")||!a.dimension().equals(b.dimension())||a.buildingOrigin().distSqr(b.buildingOrigin())>256*256||Math.abs(a.buildingOrigin().getY()-b.buildingOrigin().getY())>8)continue;
    UUID ruler=politics.titleHolder(a.settlementId()),vassal=politics.titleHolder(b.settlementId());if(!alive(s,ruler)||!alive(s,vassal))continue;
    String realm="sagadyssey:regional_"+ContainerIds.named("charter-federation:v1:"+a.settlementId()+":"+b.settlementId());politics.appointRuler(s,realm,ruler,"田作聚落原户主",now);politics.swearFealty(s,vassal,"林业聚落原户主",ruler,"田作聚落原户主",now);farm.putString("Realm",realm);wood.putString("Realm",realm);farm.putString("RealmReason","互补的粮食与林业、距离不超过256格、高差不超过8格");wood.putString("RealmReason",farm.getStringOr("RealmReason", ""));setDirty();break;
   }
  }
 }
 public void refreshAuthority(MinecraftServer s,NaturalVillageBuilding b){var row=sites.get(b.settlementId());if(row==null||!NaturalVillageLayout.chartered(b))return;var politics=PoliticalStateData.get(s);UUID holder=politics.titleHolder(b.settlementId());
  if(holder!=null&&(!alive(s,holder)||!population(s,b).contains(holder))){politics.revokeTitle(s,b.settlementId(),holder,"公职人物死亡或离开本组织，公共权利撤销",s.overworld().getGameTime());holder=null;}
  UUID previous=row.read("PublicHolder", UUIDUtil.CODEC).isPresent()?row.read("PublicHolder", UUIDUtil.CODEC).orElseThrow():null;if(Objects.equals(holder,previous))return;var rights=RightsStateData.get(s);rights.revoke(grant(b));row.remove("PublicHolder");if(holder!=null){rights.grant(new RightGrant(grant(b),NaturalVillageEconomyData.storeId(b,3),SubjectRef.character(holder),Set.of(AssetRight.MANAGE,AssetRight.TRANSFER,AssetRight.CONSUME,AssetRight.ACCESS),"本聚落现任公职；财产属于原公共机构",s.overworld().getGameTime(),null,true));row.store("PublicHolder", UUIDUtil.CODEC,holder);}setDirty();
 }
 public boolean authorized(MinecraftServer s,NaturalVillageBuilding b,UUID actor){refreshAuthority(s,b);return actor!=null&&actor.equals(PoliticalStateData.get(s).titleHolder(b.settlementId()))&&alive(s,actor)&&population(s,b).contains(actor)&&new RightsService(RightsStateData.get(s)).can(SubjectRef.character(actor),AssetRight.MANAGE,NaturalVillageEconomyData.storeId(b,3),-1,new ItemFingerprint("minecraft:white_wool",0),s.overworld().getGameTime()).status()==RightsVerdict.Status.ALLOW;}
 public String relief(MinecraftServer s,NaturalVillageBuilding b,UUID actor,UUID household){if(!authorized(s,b,actor))return "没有公共物资处分权";var home=HouseholdData.get(s).byId(household);if(home==null||!Objects.equals(home.settlementId(),b.settlementId()))return "接收户不属于本组织";
  long now=s.overworld().getGameTime();UUID id=ContainerIds.named("charter-relief:v1:"+b.settlementId()+":"+household+":"+now/24000);var prior=decisions.get(id);if(prior!=null)return prior.getStringOr("State", "");var admission=CharterTradeGovernance.publicAdmission(s,b);if(!admission.accepted())return admission.reason();if(decisions.size()>=256)return "记录容量已满";
  var l=SupplyFlowService.level(s,b.dimension());int index=Objects.equals(home.sharedStorage(),NaturalVillageLayout.at(b,NaturalVillageLayout.PANTRY))?1:4;var source=inventory(s,b,3);var target=inventory(s,b,index);if(source==null||target==null||!Objects.equals(home.sharedStorage(),NaturalVillageLayout.at(b,NaturalVillageLayout.stores(b).get(index)))||count(source,"carrot")<2)return "实际公共食物不足或目的地不可用";
  UUID from=NaturalVillageEconomyData.storeId(b,3),to=NaturalVillageEconomyData.storeId(b,index);var rights=RightsStateData.get(s);
  if(new RightsService(rights).can(SubjectRef.character(actor),AssetRight.TRANSFER,from,-1,new ItemFingerprint("minecraft:carrot",0),now).status()!=RightsVerdict.Status.ALLOW)return "现任公职仍须具备原公共转移授权";
  var t=new CompoundTag();t.store("Id", UUIDUtil.CODEC,id);t.store("Actor", UUIDUtil.CODEC,actor);t.store("Household", UUIDUtil.CODEC,household);t.store("Institution", UUIDUtil.CODEC,b.settlementId());t.putLong("At",now);t.putString("State","SUBMITTING");decisions.put(id,t);setDirty();
  var request=new TransferRequest(id,SubjectRef.character(actor),TransferIntent.GIFT,List.of(new TransferLeg(from,to,new ItemFingerprint("minecraft:carrot",0),2)),List.of(new ExpectedRevision(from,rights.context(from).revision()),new ExpectedRevision(to,rights.context(to).revision())),"现任公职批准两份公共实物救济",now,Map.of(from,SubjectRef.institution(b.settlementId())));
  var result=new TransferService(rights,TransferLedgerData.get(s)).submit(request,Map.of(from,new TransferEndpoint(from,source),to,new TransferEndpoint(to,target)),now);t.putString("State",result.successful()?"DONE":"FAILED");t.putString("Reason",result.successful()?"现任公职批准；实际公共粮扣二、接收户加二":result.reason());setDirty();WorldHistoryData.get(s).append(now,"public_relief",actor,"公共实物决策",t.getStringOr("Reason", ""),40);return t.getStringOr("State", "");
 }
 public static boolean paused(MinecraftServer s,UUID person){var d=existing(s);var h=HouseholdData.get(s).forMember(person);var t=d==null||h==null?null:d.sites.get(h.settlementId());var life=NpcLifeData.get(s).record(person);return t!=null&&t.getStringOr("Condition", "").equals("DECLINING")&&life!=null&&life.authority()==NpcWorkAuthority.INSTITUTION&&Objects.equals(life.activeWorkplaceSettlementId(),h.settlementId());}
 private void assess(MinecraftServer s,CompoundTag t,long now){var b=building(t);var people=population(s,b);if(people.isEmpty()){t.putString("Condition","EMPTY");t.putString("Reason","没有现居人口；身份、房屋和原私产保留");setDirty();return;}
  long hungry=people.stream().filter(p->{var n=NpcLifeData.get(s).needs(p);return n!=null&&n.hunger()>=900;}).count();
  if(hungry>=2){t.remove("RecoveredSince");if(!t.contains("ShortSince"))t.putLong("ShortSince",now);if(now-t.getLongOr("ShortSince", 0L)>=SagadysseyConfig.SOCIETY_DECLINE_TICKS.get()&&!t.getStringOr("Condition", "").equals("DECLINING")){t.putString("Condition","DECLINING");t.putString("Reason","至少两名现居者持续严重饥饿；暂停公共生产，允许迁移申请");WorldHistoryData.get(s).append(now,"resource_decline",b.settlementId(),"持续短缺衰退",t.getStringOr("Reason", ""),65);}}
  else{t.remove("ShortSince");if(t.getStringOr("Condition", "").equals("DECLINING")){if(!t.contains("RecoveredSince"))t.putLong("RecoveredSince",now);if(now-t.getLongOr("RecoveredSince", 0L)>=SagadysseyConfig.SOCIETY_RECOVERY_TICKS.get()){t.putString("Condition","STABLE");t.putString("Reason","严重饥饿解除并持续一个观察期，恢复公共生产");}}}
  int food=availableFood(s,b);if(!com.jgeted.sagadyssey.social.growth.GrowthLayout.supports(b)&&PublicHousingConditions.beneficiary(s,b)!=null&&food>=SagadysseyConfig.SOCIETY_FOOD_SURPLUS.get()&&!t.getStringOr("Condition", "").equals("DECLINING")){if(!t.contains("SurplusSince"))t.putLong("SurplusSince",now);if(now-t.getLongOr("SurplusSince", 0L)>=SagadysseyConfig.SOCIETY_SURPLUS_TICKS.get()&&!t.contains("Project"))startProject(s,t,now);}else t.remove("SurplusSince");setDirty();
 }
 private void startProject(MinecraftServer s,CompoundTag t,long now){var b=building(t);UUID beneficiary=PublicHousingConditions.beneficiary(s,b);if(beneficiary==null)return;var home=HouseholdData.get(s).byId(NaturalVillageLifeData.home(b));UUID holder=PoliticalStateData.get(s).titleHolder(b.settlementId());if(home==null||!authorized(s,b,holder)||!home.headCharacterId().equals(holder))return;
  var publicStore=inventory(s,b,3);var pantry=inventory(s,b,1);if(publicStore==null||pantry==null||availableFood(s,b)<SagadysseyConfig.SOCIETY_FOOD_SURPLUS.get()||count(pantry,"carrot")<4||count(pantry,"oak_log")<1)return;
  UUID from=NaturalVillageEconomyData.storeId(b,1),to=NaturalVillageEconomyData.storeId(b,3),id=ContainerIds.named("public-housing-donation:"+b.settlementId());var rights=RightsStateData.get(s);var request=new TransferRequest(id,SubjectRef.household(home.id()),TransferIntent.GIFT,List.of(new TransferLeg(from,to,new ItemFingerprint("minecraft:oak_log",0),1),new TransferLeg(from,to,new ItemFingerprint("minecraft:carrot",0),4)),List.of(new ExpectedRevision(from,rights.context(from).revision()),new ExpectedRevision(to,rights.context(to).revision())),"本户户主同意为人口住房压力捐助明确的实物",now);
  var project=new CompoundTag();project.store("Id", UUIDUtil.CODEC,id);project.store("Beneficiary", UUIDUtil.CODEC,beneficiary);project.store("FacilityOwner", UUIDUtil.CODEC,b.settlementId());project.store("ApprovedBy", UUIDUtil.CODEC,holder);project.putString("Stage","DONATING");project.putInt("PopulationAtApproval",population(s,b).size());project.putInt("PantryAtApproval",count(pantry,"carrot"));project.putInt("AuthorizedFoodAtApproval",availableFood(s,b));project.putInt("Work",0);project.putString("Reason","连续结余且住房承压，改善一张真实床位");t.put("Project",project);setDirty();
  var result=new TransferService(rights,TransferLedgerData.get(s)).submit(request,Map.of(from,new TransferEndpoint(from,pantry),to,new TransferEndpoint(to,publicStore)),now);project.putString("Stage",result.successful()?"PLANKS":"REVIEW");project.putString("Reason",result.successful()?"公共机构收到一块原木与四个胡萝卜；使用生成时三块羊毛":result.reason());setDirty();
 }
 public CompoundTag projectFor(MinecraftServer s,UUID person){for(var t:sites.values()){var b=building(t);var project=t.getCompoundOrEmpty("Project");if(person.equals(NaturalVillageLifeData.person(b,2))&&t.contains("Project")&&!Set.of("DONE","REVIEW","DONATING").contains(project.getStringOr("Stage", "")))return t;}return null;}
 public String work(NpcBase worker){var s=MinecraftApi.server(worker);var t=projectFor(s,worker.getCharacterId());if(t==null)return "DONE";var b=building(t);var p=t.getCompoundOrEmpty("Project");if(p.contains("LastWorkAt")&&p.getLongOr("LastWorkAt", 0L)==worker.level().getGameTime())return "WAIT";if(t.getStringOr("Condition", "").equals("DECLINING")){p.putString("Reason","持续食物短缺暂停公共施工；保留项目、材料和原批次");setDirty();return "WAIT";}if(worker.getCommand()!=com.jgeted.sagadyssey.npc.entity.NpcCommand.WORK||NpcLifeData.get(s).record(worker.getCharacterId()).authority()!=NpcWorkAuthority.INSTITUTION||!Objects.equals(com.jgeted.sagadyssey.social.work.NpcWorkContext.from(worker).workplaceSettlementId(),b.settlementId())||!authorized(s,b,PoliticalStateData.get(s).titleHolder(b.settlementId()))||!PublicHousingConditions.registered(s,b)){p.putString("Reason","公共劳动或本聚落空间处分授权不足，保留项目");setDirty();return "WAIT";}var publicStore=inventory(s,b,3);var pos=NaturalVillageLayout.at(b,NaturalVillageLayout.PUBLIC);if(publicStore==null||worker.blockPosition().distSqr(pos)>20)return "MOVE";
  long now=worker.level().getGameTime();UUID id=NaturalVillageEconomyData.storeId(b,3);var owner=SubjectRef.institution(b.settlementId());String stage=p.getStringOr("Stage", "");int work=p.getIntOr("Work", 0)+1;
  if(stage.equals("PLANKS")||stage.equals("BED")){boolean planks=stage.equals("PLANKS");UUID batch=ContainerIds.named("public-bed:"+b.settlementId()+":"+stage);var inputs=planks?List.of(new ProductionMaterial(new ItemFingerprint("minecraft:oak_log",0),1)):List.of(new ProductionMaterial(new ItemFingerprint("minecraft:oak_planks",0),3),new ProductionMaterial(new ItemFingerprint("minecraft:white_wool",0),3));var output=new ProductionMaterial(new ItemFingerprint(planks?"minecraft:oak_planks":"minecraft:white_bed",0),planks?4:1);int required=planks?200:400;
   try{ProductionService.begin(s,batch,worker.getCharacterId(),owner,id,publicStore,"sagadyssey:charter_"+stage.toLowerCase(),inputs,output,required,now);work=Math.min(required,work);if(work>p.getIntOr("Work", 0))p.putInt("LaborTicks",p.getIntOr("LaborTicks", 0)+1);p.putInt("Work",work);p.putLong("LastWorkAt",now);setDirty();if(work<required)return "WORK";if(!ProductionService.canAcceptOutput(s,id,publicStore,owner,output,now)){p.putString("Reason","实际成品空间不足，保留已完成劳动与原料预留");return "WAIT";}p.putBoolean("Submitting",true);ProductionService.complete(s,batch,publicStore,work,now);p.remove("Submitting");p.putString("Stage",planks?"BED":"PLACE");p.putInt("Work",0);setDirty();return "WORK";}catch(RuntimeException e){if(p.getBooleanOr("Submitting", false)){p.putString("Stage","REVIEW");p.putString("Reason","生产结算出现异常，保留材料与批次核对，不重放");setDirty();return "DONE";}p.putString("Reason",e.getMessage()==null?"实际材料尚未就绪":e.getMessage());return "WAIT";}
  }
  var l=(ServerLevel)worker.level();var foot=PublicHousingConditions.foot(b);var head=PublicHousingConditions.head(b);if(p.read("Beneficiary", UUIDUtil.CODEC).isPresent()&&!PublicHousingConditions.canPlace(s,b,p.read("Beneficiary", UUIDUtil.CODEC).orElseThrow()))return "WAIT";if(!l.getBlockState(foot).isAir()||!l.getBlockState(head).isAir()||!l.getBlockState(foot.below()).isFaceSturdy(l,foot.below(),Direction.UP)||!l.getBlockState(head.below()).isFaceSturdy(l,head.below(),Direction.UP)||count(publicStore,"white_bed")<1||count(publicStore,"carrot")<4){p.putString("Reason","既定位置、地面或实物床位与口粮不足，保留成品不另造");setDirty();return "WAIT";}
  var rights=RightsStateData.get(s);var before=NaturalVillageEconomyData.items(publicStore,s.registryAccess());var title=rights.snapshotFor(Set.of(id));p.putBoolean("Submitting",true);setDirty();try{
   var consume=new ConsumptionService(rights);if(!consume.consume(id,publicStore,owner,new ItemFingerprint("minecraft:white_bed",0),1,"public-bed-place",now).successful()||!consume.consume(id,publicStore,owner,new ItemFingerprint("minecraft:carrot",0),4,"public-bed-rations",now).successful())throw new IllegalStateException("床位或施工口粮不可处分");
   Direction facing=(Math.abs(head.getX()-foot.getX())+Math.abs(head.getZ()-foot.getZ())==1 ? Direction.getNearest(head.getX()-foot.getX(),0,head.getZ()-foot.getZ(),Direction.NORTH) : null);if(facing==null)throw new IllegalStateException("床位方向无效");var state=Blocks.WHITE_BED.defaultBlockState().setValue(BedBlock.FACING,facing);int flags=Block.UPDATE_CLIENTS|Block.UPDATE_KNOWN_SHAPE;if(!l.setBlock(foot,state.setValue(BedBlock.PART,BedPart.FOOT),flags)||!l.setBlock(head,state.setValue(BedBlock.PART,BedPart.HEAD),flags))throw new IllegalStateException("床位放置被拒绝");if(p.read("Beneficiary", UUIDUtil.CODEC).isPresent()&&!NpcLifeData.get(s).assignBed(p.read("Beneficiary", UUIDUtil.CODEC).orElseThrow(),b.dimension(),head,"本聚落公共改善床位",now))throw new IllegalStateException("真实床位交接被拒绝");p.putLong("FacilityHead",head.asLong());p.putLong("FacilityFoot",foot.asLong());NpcLifeData.get(s).feed(worker.getCharacterId(),880,"四份实际公共施工口粮",now);p.putString("Stage","DONE");p.remove("Submitting");p.putLong("Completed",now);p.putString("Reason","一块原木制四木板，三木板加三羊毛制床，余一木板；四份口粮已实际消费");t.putInt("ExtraBeds",1);setDirty();WorldHistoryData.get(s).append(now,"public_housing_improved",p.read("ApprovedBy", UUIDUtil.CODEC).orElseThrow(),"真实公共设施改善",p.getStringOr("Reason", ""),55);return "DONE";
  }catch(RuntimeException e){var restore=NaturalVillageEconomyData.inventory(before,s.registryAccess());for(int i=0;i<27;i++)publicStore.setItem(i,restore.getItem(i));rights.restore(title);l.setBlock(foot,Blocks.AIR.defaultBlockState(),Block.UPDATE_CLIENTS|Block.UPDATE_KNOWN_SHAPE);l.setBlock(head,Blocks.AIR.defaultBlockState(),Block.UPDATE_CLIENTS|Block.UPDATE_KNOWN_SHAPE);p.putString("Stage","REVIEW");p.putString("Reason","放置失败并恢复本次实物；需核对 "+e.getMessage());p.remove("Submitting");setDirty();return "DONE";}
 }
 public void tick(MinecraftServer s){long now=s.overworld().getGameTime();enroll(s);for(var t:sites.values()){var b=building(t);refreshAuthority(s,b);if(now%200==0)assess(s,t,now);}CharterTradeGovernance.tick(s,this);}
 @Override public CompoundTag save(CompoundTag t,HolderLookup.Provider lookup){t.putInt("Schema",1);var list=new ListTag();sites.values().forEach(a->list.add(a.copy()));t.put("Sites",list);var ds=new ListTag();decisions.values().forEach(a->ds.add(a.copy()));t.put("Decisions",ds);return t;}
 public static NaturalPolityData load(CompoundTag t,HolderLookup.Provider lookup){if(t.getIntOr("Schema", 0)!=1)throw new IllegalArgumentException("Unknown charter schema");var d=new NaturalPolityData();for(var e:com.jgeted.sagadyssey.worldsim.PersistentDataAccess.compounds(t,"Sites")){var a=((CompoundTag)e).copy();var b=building(a);if(d.sites.putIfAbsent(b.settlementId(),a)!=null||d.sites.size()>4)throw new IllegalArgumentException("Duplicate charter");var p=a.getCompoundOrEmpty("Project");if(a.contains("Project")&&(!p.read("Id", UUIDUtil.CODEC).isPresent()||!p.read("ApprovedBy", UUIDUtil.CODEC).isPresent()||!Set.of("DONATING","PLANKS","BED","PLACE","DONE","REVIEW").contains(p.getStringOr("Stage", ""))||p.getIntOr("Work", 0)<0))throw new IllegalArgumentException("Invalid public project");if(p.contains("Beneficiary")&&(!p.read("Beneficiary", UUIDUtil.CODEC).isPresent()||!p.read("FacilityOwner", UUIDUtil.CODEC).isPresent()||!p.read("FacilityOwner", UUIDUtil.CODEC).orElseThrow().equals(b.settlementId())||p.getIntOr("LaborTicks", 0)<0||p.getIntOr("LaborTicks", 0)>600))throw new IllegalArgumentException("Invalid bounded housing assignment");if(p.getBooleanOr("Submitting", false)||p.getStringOr("Stage", "").equals("DONATING")){p.putString("Stage","REVIEW");p.putString("Reason","公共项目转移或放置中断，保留回执和实物，不自动重放");}}for(var e:com.jgeted.sagadyssey.worldsim.PersistentDataAccess.compounds(t,"Decisions")){var a=((CompoundTag)e).copy();if(a.getStringOr("State", "").equals("SUBMITTING"))a.putString("State","REVIEW");if(d.decisions.putIfAbsent(a.read("Id", UUIDUtil.CODEC).orElseThrow(),a)!=null||d.decisions.size()>256)throw new IllegalArgumentException("Duplicate public decision");}CharterTradeGovernance.validate(d);LimitedConflictGovernance.validate(d);return d;}
 @SubscribeEvent public static void post(net.neoforged.neoforge.event.tick.ServerTickEvent.Post e){if(e.getServer().overworld().getGameTime()%20==0&&NaturalVillageLifeData.existing(e.getServer())!=null)get(e.getServer()).tick(e.getServer());}
}
